param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'integer-default-span-parse-overloads-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
function UnitsText($units){if($null -eq $units){return $null};return [string]::new([char[]]([int[]]$units))}
$rows=[Collections.Generic.List[object]]::new();$metadata=[Collections.Generic.List[object]]::new();foreach($name in $plan.types){$native=[type]::GetType($name,$true);foreach($route in @('chars','bytes')){$element=[char];if($route -eq 'bytes'){$element=[byte]};$span=[ReadOnlySpan``1].MakeGenericType($element);$method=$native.GetMethod('Parse',[type[]]@($span,[Globalization.NumberStyles],[IFormatProvider]));$parameters=$method.GetParameters();if(-not $parameters[1].IsOptional -or [int]$parameters[1].DefaultValue -ne 7 -or -not $parameters[2].IsOptional -or $null -ne $parameters[2].DefaultValue){throw 'Unexpected native optional span defaults'};$metadata.Add([ordered]@{type=$name;route=$route;styleOptional=$true;styleDefault=7;providerOptional=$true;providerDefault=$null})
$dm=[Reflection.Emit.DynamicMethod]::new('DefaultIntegerSpan',[object],[type[]]@([object]));$il=$dm.GetILGenerator();$op=[Reflection.Emit.OpCodes];$il.Emit($op::Ldarg_0);if($route -eq 'chars'){$il.Emit($op::Castclass,[string]);$il.Emit($op::Call,[MemoryExtensions].GetMethod('AsSpan',[type[]]@([string])))}else{$il.Emit($op::Castclass,[byte[]]);$il.Emit($op::Newobj,$span.GetConstructor([type[]]@([byte[]])))};$il.Emit($op::Ldc_I4_7);$il.Emit($op::Ldnull);$il.Emit($op::Call,$method);$il.Emit($op::Box,$native);$il.Emit($op::Ret);$delegate=$dm.CreateDelegate([Func[object,object]])
for($index=0;$index -lt $plan.texts.Count;$index++){$text=UnitsText $plan.texts[$index];$arguments=[object[]]::new(1);if($route -eq 'chars'){$arguments[0]=$text}else{$content='';if($null -ne $text){$content=$text};$arguments[0]=[Text.Encoding]::UTF8.GetBytes($content)};try{$value=$delegate.DynamicInvoke($arguments);$result=[ordered]@{ok=$true;value=$value.ToString()}}catch{$result=Failure $_};$rows.Add([ordered]@{type=$name;route=$route;index=$index;result=$result})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';metadata=$metadata.ToArray();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS default integer span Parse: $($rows.Count) calls and $($metadata.Count) optional-default controls"
